contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(uint unlockTimeArg, uint amount) public payable {
        require(amount > 0, "amount must be nonzero");
        require(address(this).balance >= amount, "insufficient test balance");

        HolderBefore memory beforeState;
        beforeState.balance = _balanceOf(address(this));
        beforeState.unlockTime = _unlockTimeOf(address(this));

        bool reverted;
        try c.Put{value: amount}(unlockTimeArg) {
            reverted = false;
        } catch {
            reverted = true;
        }

        HolderAfter memory afterState;
        afterState.balance = _balanceOf(address(this));
        afterState.unlockTime = _unlockTimeOf(address(this));

        bool expectedRevert = unlockTimeArg <= block.timestamp;
        assert(
            reverted == expectedRevert &&
            (reverted ||
                (afterState.balance == beforeState.balance + amount &&
                 afterState.unlockTime == unlockTimeArg))
        );
    }

    struct HolderBefore {
        uint balance;
        uint unlockTime;
    }

    struct HolderAfter {
        uint balance;
        uint unlockTime;
    }

    function _balanceOf(address who) internal view returns (uint) {
        (uint unlockTime, uint balance) = c.Acc(who);
        unlockTime;
        return balance;
    }

    function _unlockTimeOf(address who) internal view returns (uint) {
        (uint unlockTime, uint balance) = c.Acc(who);
        balance;
        return unlockTime;
    }

    receive() external payable {}
}

